  console.log('[AUDIT] Starting local HTTP server on port 8099 for isolation...');
  const { server, port } = await index.startServer(8099, '127.0.0.1');
  assert.strictEqual(port, 8099, 'Port should be 8099');

  try {
    // 1. Health endpoint
    console.log('[AUDIT] Testing /health endpoint...');
    const health = await httpClient.getJson('http://127.0.0.1:8099/health');
